import{_ as a,o as t,c as d,a3 as r}from"./chunks/framework.CP7W6Imw.js";const f=JSON.parse('{"title":"Incremental Software Update","description":"","frontmatter":{"title":"Incremental Software Update"},"headers":[],"relativePath":"00.docs/040.upgrade/030.incremental-update.md","filePath":"00.docs/040.upgrade/030.incremental-update.md","lastUpdated":1782050991000}'),n={name:"00.docs/040.upgrade/030.incremental-update.md"};function l(o,e,i,s,c,p){return t(),d("div",null,[...e[0]||(e[0]=[r('<p>The full update feature is <code>free</code> and has a demo example, see <a href="/00.docs/040.upgrade/020.full-update">here</a>. The incremental update is a <code>paid plugin</code>.</p><h3 id="differences" tabindex="-1">Differences <a class="header-anchor" href="#differences" aria-label="Permalink to &quot;Differences&quot;">​</a></h3><ul><li>Full update updates everything including Electron, Node.js, and all dependencies. Incremental update only updates app.asar and provides the ability to update additional resource directories.</li><li>Full update deletes local data, while incremental update does not affect local data.</li><li>The <code>auto-update</code> feature of full update may require purchasing macOS and Windows developer certificates.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you are only developing personal daily tools or have a small number of users, then full update or overwrite installation can meet your needs.</p><p>If you need a better update experience or want to bypass purchasing certificates, then incremental update is more suitable for you.</p></div><p><a href="/08.plugins/01.introduction">View documentation</a></p>',5)])])}const m=a(n,[["render",l]]);export{f as __pageData,m as default};
